using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;
namespace CalendarWeather;
internal static class ScrollFooterVerification {
 static T? Find<T>(DependencyObject root) where T:DependencyObject {if(root is T target)return target;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=Find<T>(VisualTreeHelper.GetChild(root,i));if(found!=null)return found;}return null;}
 static bool Fits(SettingsPanel panel){foreach(var page in panel.Pages.Where(x=>x.IsVisible))foreach(var child in page.Children.OfType<FrameworkElement>().Where(x=>x.IsVisible)){var bottom=child.TransformToAncestor(panel).Transform(new Point(child.ActualWidth,child.ActualHeight));if(bottom.Y>panel.ActualHeight+1||bottom.X>panel.ActualWidth+1)return false;}return true;}
 static void Capture(Window window,int page){var dpi=VisualTreeHelper.GetDpi(window);var bmp=new RenderTargetBitmap((int)(window.ActualWidth*dpi.DpiScaleX),(int)(window.ActualHeight*dpi.DpiScaleY),96*dpi.DpiScaleX,96*dpi.DpiScaleY,PixelFormats.Pbgra32);bmp.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bmp));using var file=File.Create(Path.Combine(Directory.GetParent(Store.Root)!.FullName,$"settings-page-{page}.png"));encoder.Save(file);}
 internal static async Task<bool> Run(Window window){var panel=Find<SettingsPanel>(window);if(panel==null||panel.Pages.Count!=5||Find<ScrollViewer>(panel)!=null||window.Owner is not MainWindow main)return false;bool valid=true;double height=window.Height;var oldAccounts=main.accounts.ToList();var oldSnapshots=main.snapshots.ToArray();try{window.Height=460;main.accounts.Clear();for(int a=0;a<7;a++)main.accounts.Add(new Account{Email=$"Conta de exemplo {a+1}",Provider="Google"});main.snapshots.Clear();main.snapshots["fixture"]=new CalendarSnapshot(new(),Enumerable.Range(1,19).Select(i=>new CalendarInfo(i.ToString(),$"Calendário de exemplo {i}","#4285F4")).ToList(),DateTimeOffset.Now);panel.RefreshAccounts();panel.RefreshState();for(int i=0;i<panel.Pages.Count;i++){panel.SelectPage(i);window.UpdateLayout();await Task.Delay(60);valid&=Fits(panel);if(i==3){var provider=panel.Pages[i].Children.OfType<Grid>().SelectMany(x=>x.Children.OfType<ComboBox>()).FirstOrDefault();if(provider!=null)provider.SelectedIndex=1;window.UpdateLayout();await Task.Delay(60);valid&=Fits(panel);}Capture(window,i);}var next=FindButton(panel.Pages[4],"Próxima página");if(next==null)return false;for(int page=1;page<5;page++){next.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));window.UpdateLayout();await Task.Delay(60);valid&=Fits(panel);next=FindButton(panel.Pages[4],"Próxima página")!;}valid&=!next.IsEnabled;return valid;}finally{main.accounts.Clear();main.accounts.AddRange(oldAccounts);main.snapshots.Clear();foreach(var item in oldSnapshots)main.snapshots[item.Key]=item.Value;panel.RefreshAccounts();panel.RefreshState();panel.SelectPage(0);window.Height=height;window.UpdateLayout();}}
 static Button? FindButton(DependencyObject root,string name){if(root is Button button&&System.Windows.Automation.AutomationProperties.GetName(button)==name)return button;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=FindButton(VisualTreeHelper.GetChild(root,i),name);if(found!=null)return found;}return null;}
}
